python3 << 'EOF'
import json
from pathlib import Path
import os

# Find all models with Scandinavian results
results_dir = Path("/root/.cache/mteb/results/results")
model_scores = {}

for model_dir in results_dir.iterdir():
    if not model_dir.is_dir():
        continue

    model_name = model_dir.name

    # Look for task JSON files in subdirectories (one level deep)
    for revision_dir in model_dir.iterdir():
        if not revision_dir.is_dir():
            continue

        task_files = list(revision_dir.glob("*.json"))
        if not task_files:
            continue

        # Check if this model has any Scandinavian tasks
        scandinavian_tasks = [
            'AngryTweetsClassification', 'BornholmBitextMining', 'DKHateClassification',
            'DalajClassification', 'DanFeverRetrieval', 'DanishPoliticalCommentsClassification',
            'LccSentimentClassification', 'MassiveIntentClassification', 'MassiveScenarioClassification',
            'NoRecClassification', 'NorQuadRetrieval', 'NordicLangClassification',
            'NorwegianCourtsBitextMining', 'NorwegianParliamentClassification',
            'SNLHierarchicalClusteringP2P', 'SNLHierarchicalClusteringS2S', 'SNLRetrieval',
            'SwednClusteringFastS2S', 'SwednClusteringP2P', 'SwednRetrieval',
            'SweFaqRetrieval', 'Swedish SentimentClassification', 'SweRecClassification',
            'TV2Nordretrieval', 'TwitterHjerneRetrieval', 'VGHierarchicalClusteringP2P',
            'VGHierarchicalClusteringS2S'
        ]

        has_scandi = False
        for task_file in task_files:
            if any(scandi_task in task_file.name for scandi_task in scandinavian_tasks):
                has_scandi = True
                break

        if has_scandi:
            # Compute mean score across Scandinavian tasks
            scores = []
            for task_file in task_files:
                if any(scandi_task in task_file.name for scandi_task in scandinavian_tasks):
                    try:
                        with open(task_file) as f:
                            data = json.load(f)
                        # Extract the main score (usually under 'test' or first metric)
                        if isinstance(data, dict):
                            if 'test' in data:
                                test_data = data['test']
                                if isinstance(test_data, dict):
                                    # Get the first numeric value we can find
                                    for k, v in test_data.items():
                                        if isinstance(v, (int, float)):
                                            scores.append(v)
                                            break
                            elif 'test_mteb_eval' in data:
                                for k, v in data['test_mteb_eval'].items():
                                    if isinstance(v, (int, float)) and v <= 1.0:
                                        scores.append(v)
                                        break
                    except:
                        pass

            if scores:
                mean_score = sum(scores) / len(scores)
                model_scores[model_name] = mean_score
                print(f"{model_name}: {mean_score:.4f} (from {len(scores)} tasks)")

# Find top 10 models
if model_scores:
    sorted_models = sorted(model_scores.items(), key=lambda x: x[1], reverse=True)
    print("\n=== Top 10 Models ===")
    for i, (model, score) in enumerate(sorted_models[:10], 1):
        print(f"{i}. {model}: {score:.4f}")
